	@Test
	public void testGetXpForLevel()
	{
		int xp = Experience.getXpForLevel(99);
		assertEquals(XP_FOR_99, xp);

		xp = Experience.getXpForLevel(126);
		assertEquals(XP_FOR_126, xp);

		xp = Experience.getXpForLevel(1);
		assertEquals(0, xp);
	}

